(r, big) => {
    const n = big ? 100000 : r.int(1, 7);
    const lab = r.shuffle(Array.from({ length: n }, (_, i) => i));
    const edges = [];
    for (let i = 1; i < n; i++) edges.push([lab[i], lab[r.int(Math.max(0, i - 5), i - 1)]]); // a random tree
    const has = new Set(edges.map(([a, b]) => Math.min(a, b) + "," + Math.max(a, b)));
    const mode = big ? r.pick([0, 0, 3]) : r.int(0, 3); // 0: keep, 1: drop a cable, 2: add a cable, 3: both
    if ((mode === 1 || mode === 3) && edges.length) edges.splice(r.int(0, edges.length - 1), 1);
    if ((mode === 2 || mode === 3) && n > 2) {
      for (let t = 0; t < 20; t++) {
        const a = r.int(0, n - 1), b = r.int(0, n - 1), k = Math.min(a, b) + "," + Math.max(a, b);
        if (a !== b && !has.has(k)) { edges.push([a, b]); break; }
      }
    }
    return [n, r.shuffle(edges.map(e => (r.bool() ? e : [e[1], e[0]])))];
  }

