function isTree(n: number, edges: number[][]): boolean {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const seen = new Array(n).fill(false);
  seen[0] = true;
  const stack: number[][] = [[0, -1]]; // [machine, the machine we came from]
  let count = 1;
  while (stack.length) {
    const [u, parent] = stack.pop()!;
    for (const v of adj[u]) {
      if (v === parent) continue; // the cable we arrived on
      if (seen[v]) return false; // a second route to v: loop
      seen[v] = true;
      count++;
      stack.push([v, u]);
    }
  }
  return count === n;
}

